package com.shoplab.helpdesk.chat.domain.model;

import com.shoplab.helpdesk.shared.exception.ExceptionUtil;
import com.shoplab.helpdesk.shared.exception.ResponseCodeEnum;
import java.util.Locale;
import java.util.Optional;
import java.util.regex.Pattern;

/**
 * Identifier of a conversation: a UUID in its canonical text form, generated by the client. It is kept in lower case
 * so the two spellings of a UUID are the same conversation. It is a secret of whoever holds it: it is never logged, put
 * in a metric or returned.
 *
 * @param value the canonical, lower-case text of the UUID
 */
public record ConversationId(String value) {

    private static final Pattern CANONICAL_UUID =
            Pattern.compile("[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}");

    public ConversationId {
        if (value == null || !CANONICAL_UUID.matcher(value).matches()) {
            throw ExceptionUtil.business(ResponseCodeEnum.INVALID_CONVERSATION_ID);
        }
        value = value.toLowerCase(Locale.ROOT);
    }

    /** No identifier means no memory; anything that is not a canonical UUID is an invalid request. */
    public static Optional<ConversationId> optional(String raw) {
        return raw == null ? Optional.empty() : Optional.of(new ConversationId(raw));
    }
}
